import { test, expect } from '@playwright/test';

test.describe('Product List Display - Complete Cards', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/inventory');
  });

  test('should display 6 complete product cards with non-empty names and prices starting with $', async ({ page }) => {
    // Verify login page is visible
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Verify login form is visible
    const emailInput = page.getByLabel(/email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /log in/i });

    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    // Fill in login credentials
    await emailInput.fill('standard_user@example.com');
    await passwordInput.fill('secret_sauce');

    // Click login button
    await loginButton.click();

    // Verify login success message
    const successMessage = page.getByText(/logged in successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify product list is displayed
    const productList = page.getByRole('list', { name: /products/i });
    await expect(productList).toBeVisible();

    // Verify there are exactly 6 product cards
    const productCards = page.locator('[data-testid="product-card"]');
    const cardCount = await productCards.count();
    expect(cardCount).toBe(6);

    // Verify each card has a name element with non-empty text
    for (let i = 0; i < 6; i++) {
      const card = await productCards.nth(i);
      const name = await card.getByRole('heading').textContent();
      expect(name).toBeDefined();
      expect(name).not.toBe('');
    }

    // Verify each card has a price element with text starting with $
    for (let i = 0; i < 6; i++) {
      const card = await productCards.nth(i);
      const price = await card.getByRole('paragraph').textContent();
      expect(price).toMatch(/^\$/);
    }
  });

  test('should handle empty product list with error message', async ({ page }) => {
    // Verify login page is visible
    const loginButton = page.getByRole('button', { name: /log in/i });
    await expect(loginButton).toBeVisible();

    // Click login button
    await loginButton.click();

    // Verify login form is visible
    const emailInput = page.getByLabel(/email/i);
    const passwordInput = page.getByLabel(/password/i);
    const loginButton = page.getByRole('button', { name: /log in/i });

    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    // Fill in login credentials
    await emailInput.fill('standard_user@example.com');
    await passwordInput.fill('wrong_password');

    // Click login button
    await loginButton.click();

    // Verify login failed message
    const errorMessage = page.getByText(/invalid credentials/i);
    await expect(errorMessage).toBeVisible();

    // Verify product list is empty
    const productList = page.getByRole('list', { name: /products/i });
    await expect(productList).toBeVisible();
    const productCards = page.locator('[data-testid="product-card"]');
    const cardCount = await productCards.count();
    expect(cardCount).toBe(0);

    // Verify error message is displayed
    const errorText = page.getByText(/please try again/i);
    await expect(errorText).toBeVisible();
  });
});
